{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "log", "sql": "SELECT min(time) AS first_log, max(time) AS last_log, count(*) AS n, min(message) AS sample FROM abnormal_logs WHERE service_name='shipping'", "claim": "Shipping logs stop after a SIGTERM at 03:49:50; all 82 abnormal shipping logs fall within about 0.3 s."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, min(value) AS vmin, max(value) AS vmax FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'shipping%' GROUP BY ALL", "claim": "The shipping pod restart counter rises from 0 to 1 during the abnormal window; normal period stays at 0."},
        {"kind": "trace", "sql": "SELECT 'normal' AS period, count(*) AS shipping_spans FROM normal_traces WHERE service_name='shipping' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='shipping'", "claim": "Shipping emits 6 spans in the normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name='HTTP POST' GROUP BY ALL", "claim": "All 9 checkout HTTP POST calls to shipping in the abnormal window return Error after about 1.3 ms."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('HTTP POST','oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL", "claim": "Checkout's outgoing shipping HTTP POST and its PlaceOrder server span both return Error in the abnormal window; normal is Unset/200."}
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST /api/checkout' GROUP BY ALL", "claim": "Frontend POST /api/checkout returns HTTP 500 on all 10 abnormal requests; normal shows 200 on all requests."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY ALL", "claim": "Frontend-proxy ingress returns 500 on 26 abnormal requests, matching frontend's failed checkout and product-review routes."}
      ]
    }
  ]
}
